#!/usr/bin/env python3
"""Build editorial navigation from approved public records, without changing them."""
from projection_utils import preserve_chrome
from pathlib import Path
import json,hashlib,html,re
from urllib.parse import urlencode
ROOT=Path(__file__).resolve().parents[1];D=ROOT/'docs';OUT=D/'questions';VERSION='0.5.6';HOST='https://ai-governance-trust-commons.github.io/vocabulary-commons/'
def esc(x):return html.escape(str(x),quote=True)
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def build():
 raw=(D/'evidence/evidence.json').read_bytes();d=json.loads(raw);source=json.loads((ROOT/'site-tools/research_paths.json').read_text());paths=source['paths']
 ev={e['id']:e for e in d['evidence']};ss={s['id']:s for s in d['sources']};terms={t['id']:t for t in d['terms']};glossary=json.loads((D/'data/glossary.json').read_text());routes={t['term']:t['slug'] for t in glossary['terms']};coverage=json.loads((D/'evidence/coverage/coverage.json').read_text());counts={t['id']:t for t in coverage['terms']}
 if coverage['dataset_sha256']!=hashlib.sha256(raw).hexdigest():raise ValueError('Refresh coverage before building research paths')
 if len({p['slug'] for p in paths})!=len(paths):raise ValueError('Duplicate path slug')
 for p in paths:
  if not re.fullmatch('[a-z0-9]+(?:-[a-z0-9]+)*',p['slug']):raise ValueError('Invalid slug')
  if any(t not in terms for t in p['terms']):raise ValueError('Unknown term')
  if len({r['id'] for r in p['readings']})!=len(p['readings']):raise ValueError('Duplicate reading')
  for r in p['readings']:
   if r['id'] not in ev:raise ValueError('Unpublished or withdrawn reading: '+r['id'])
   if not any(x['from_id']==r['id'] and x['to_id'] in p['terms'] for x in d['relationships']):raise ValueError('Reading lacks an existing relationship to any path term: '+r['id'])
 home=(D/'index.html').read_text();baseheader=re.search(r'<header class="site-header">[\s\S]*?</header>',home)[0];basefooter=re.search(r'<footer class="site-footer">[\s\S]*?</footer>',home)[0]
 def page(title,description,body,depth,slug='',script=False):
  prefix='../'*depth
  header=baseheader.replace('href="./','href="'+prefix).replace('aria-current="page"','').replace('href="'+prefix+'questions/"','href="'+prefix+'questions/" aria-current="page"')
  footer=basefooter.replace('href="./','href="'+prefix)
  asset='../' if depth==2 else ''
  rendered = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>'+esc(title)+' | Vocabulary Commons</title><meta name="description" content="'+esc(description)+'"><link rel="canonical" href="'+HOST+'questions/'+slug+'"><link rel="stylesheet" href="'+prefix+'assets/style.css"><link rel="stylesheet" href="'+asset+'paths.css"><link rel="alternate" type="application/json" href="'+asset+'paths.json" title="Research paths data"></head><body><a class="skip" href="#content">Skip to main content</a>'+header+'<main id="content" class="paths-main">'+body+'</main>'+footer+'<script defer src="'+prefix+'assets/app.js"></script>'+('<script defer src="paths.js"></script>' if script else '')+'</body></html>\n'
  return preserve_chrome(OUT/slug/'index.html', rendered)
 cards=[];jsonpaths=[]
 for i,p in enumerate(paths):
  termnames=[terms[t]['name'] for t in p['terms']];search=' '.join([p['question'],p['label'],p['intro'],*termnames]).casefold()
  cards.append('<article class="path-card" data-search="'+esc(search)+'"><p class="path-label">'+str(i+1).zfill(2)+' · '+esc(p['label'])+'</p><h2><a href="'+p['slug']+'/">'+esc(p['question'])+'</a></h2><p>'+esc(p['intro'])+'</p><p class="path-meta">'+str(len(p['readings']))+' selected findings · '+str(len(p['terms']))+' related terms</p><p><a href="'+p['slug']+'/">Start this research path →</a></p></article>')
  termcards=[]
  for tid in p['terms']:
   c=counts[tid];missing=not c['finding_count'];status='No recorded evidence relationship' if missing else str(c['finding_count'])+' linked findings · '+str(c['recorded_family_count'])+' recorded families'
   termcards.append('<article class="path-term"><h3><a href="../../terms/'+routes[terms[tid]['name']]+'/">'+esc(terms[tid]['name'])+'</a></h3><p>'+status+'</p><nav aria-label="Explore '+esc(terms[tid]['name'])+'"><a href="../../evidence/?'+esc(urlencode({'term':tid}))+'">Library results</a><a href="../../evidence/coverage/#'+tid+'">Coverage and gaps</a></nav></article>')
  readings=[];jsonreadings=[]
  for j,r in enumerate(p['readings'],1):
   e=ev[r['id']];families=sorted({ss[sid]['independence_group'] for sid in e['source_ids'] if ss[sid].get('independence_group')});sources=[]
   for sid in e['source_ids']:
    s=ss[sid];sources.append('<div class="path-source"><p><strong>'+sid+' · '+esc(s['title'])+'</strong></p><p>'+esc(', '.join(s.get('authors',[])) or s.get('issuing_body') or s['publisher'])+' · '+esc(s['publisher'])+' · '+esc(s.get('publication_date') or 'Publication date not recorded')+'</p><p><a href="'+esc(s['url'])+'" rel="noopener noreferrer">Read original source →</a></p><p><strong>Finding location:</strong> '+esc(e.get('source_locations',{}).get(sid,s.get('locator','Not recorded')))+'</p><p><strong>Version, provenance and discovery:</strong> '+esc(s.get('version_note','Not recorded'))+'</p><p><strong>Source inspection:</strong> '+esc(s.get('verification',{}).get('status','Not recorded'))+'</p></div>')
   label=e.get('evidence_standing_label',e['evidence_standing'])
   readings.append('<article class="path-finding" id="'+e['id']+'"><p class="path-label">Reading '+str(j)+' · '+e['id']+' · '+esc(label)+'</p><h3>'+esc(r['heading'])+'</h3><p class="path-why"><strong>Why this is selected — Commons editorial note:</strong> '+esc(r['why'])+'</p><p><strong>Finding as recorded in the Library:</strong> '+esc(e['observation'])+'</p><p class="path-limits"><strong>Limits to retain:</strong> '+esc(e['limitations'])+'</p><p><a href="../../evidence/#'+e['id']+'">Open full record, interpretation and verification →</a></p><details><summary>Original citations and source context</summary>'+''.join(sources)+'<p><strong>Recorded family identifiers:</strong> '+esc(', '.join(families) or 'Not recorded')+'. These labels do not certify independent corroboration.</p><p><strong>Independent verification:</strong> '+esc(e.get('verification_status','Not recorded'))+'. <strong>Individual human review:</strong> '+esc(e.get('publication_record',{}).get('individual_human_review','Not recorded'))+'.</p></details></article>')
   jsonreadings.append({**r,'observation':e['observation'],'limitations':e['limitations'],'evidence_standing_label':label,'record_url':HOST+'evidence/#'+e['id'],'source_ids':e['source_ids'],'sources':[ss[sid] for sid in e['source_ids']],'recorded_family_ids':families,'verification_status':e.get('verification_status'),'publication_record':e.get('publication_record')})
  body='<p class="path-label">Research path '+str(i+1).zfill(2)+' / '+str(len(paths))+' · '+esc(p['label'])+'</p><h1>'+esc(p['question'])+'</h1><p class="path-lead">'+esc(p['intro'])+'</p><p class="path-basis">Editorial path '+VERSION+' · Public dataset '+esc(d['dataset_version'])+' · Selected findings, not an exhaustive review.</p><nav class="path-tools" aria-label="Research tools"><a href="../">All research paths</a><a href="../../evidence/">Search the Library</a><a href="../../evidence/coverage/">Evidence coverage and gaps</a><a href="../paths.json" download>Download paths data</a></nav><aside class="path-caution"><strong>Keep the comparison bounded.</strong><p>'+esc(p['caution'])+'</p><p>Selections express editorial relevance. Publication is not endorsement, independent verification or validation of a term.</p></aside><section class="path-section"><h2>Questions to carry into the reading</h2><ol class="path-prompts">'+''.join('<li>'+esc(q)+'</li>' for q in p['prompts'])+'</ol></section><section class="path-section"><h2>Read, compare, keep the limits</h2><p>Read each source’s finding and limits together. Open its citation context to follow the original publication and recorded version.</p>'+''.join(readings)+'</section><section class="path-section"><h2>Explore the related vocabulary</h2><p>These are the existing question-to-term navigation links. Not every selected finding is linked to every term. The full Library record identifies its explicit relationships.</p><div class="path-term-grid">'+''.join(termcards)+'</div></section><section class="path-section"><h2>What would strengthen the answer?</h2><p>Look for comparable tasks and populations, independent source families, contrary results and directly public original sources. A useful contribution can be a correction, a missing connection or a reason the evidence does not fit.</p><nav class="path-tools"><a href="../../participate/">Contribute or challenge this path →</a><a href="../../evidence/policy.html">Read publication and verification policy</a></nav></section><nav class="path-footer-nav" aria-label="Other research paths">'+('<a href="../'+paths[i-1]['slug']+'/">← '+esc(paths[i-1]['label'])+'</a>' if i else '<a href="../">← All research paths</a>')+('<a href="../'+paths[i+1]['slug']+'/">'+esc(paths[i+1]['label'])+' →</a>' if i+1<len(paths) else '<a href="../">All research paths →</a>')+'</nav>'
  folder=OUT/p['slug'];folder.mkdir(parents=True,exist_ok=True);(folder/'index.html').write_text(page(p['question'],p['intro'],body,2,p['slug']+'/'))
  jsonpaths.append({**p,'url':HOST+'questions/'+p['slug']+'/','readings':jsonreadings})
 body='<p class="eyebrow">Start with a question. Follow the evidence.</p><h1>Research paths for<br>AI governance questions.</h1><p class="path-lead">Start with a question about oversight, reliance, assurance or governability. Compare selected findings, original sources and their limitations.</p><p class="path-basis">Editorial paths '+VERSION+' · Public dataset '+esc(d['dataset_version'])+' · The founding glossary remains unchanged.</p><aside class="path-caution"><strong>Starting points, not settled answers.</strong><p>These paths are editorial navigation aids outside the frozen founding publication. Selected findings are not exhaustive reviews or quality rankings. They can describe experiments, attributed accounts, reviews or formal arguments; these are different kinds of evidence.</p></aside><nav class="path-tools" aria-label="Research tools"><a href="../evidence/">Search all evidence</a><a href="../evidence/coverage/">Explore coverage and gaps</a><a href="paths.json" download>Download research paths</a><a href="../evidence/machine/">Machine access and citations</a></nav><div class="path-search" hidden><label for="path-search">Find a question or related term</label><div class="path-search-row"><input id="path-search" type="search" placeholder="Try feedback, competence or oversight" autocomplete="off"><button id="path-reset" type="button">Reset</button></div></div><p id="path-status" role="status" aria-live="polite">8 research paths. Each includes findings and their limits.</p><div class="path-grid">'+''.join(cards)+'</div><p id="path-empty" hidden>No research paths match. Try another term or reset the search.</p><section class="path-section" aria-labelledby="discussion-heading"><p class="eyebrow">Ideas under discussion</p><h2 id="discussion-heading">What connects events across time?</h2><p>Explore concepts and questions for further consideration and development. This discussion examines possible event chains; it is exploratory analysis outside the founding glossary and Library findings.</p><p><a href="event-chains/">Explore event-chain questions →</a></p></section><section class="path-section path-reading-method"><h2>How to use a path</h2><ol><li>Carry the comparison questions into the selected readings.</li><li>Keep the recorded finding and its limitations together.</li><li>Follow original citations and inspect the full Library record for interpretation, verification and explicit term relationships.</li><li>Use coverage to identify curation gaps; broaden the Library search beyond the selected readings.</li></ol><p>Source-family labels help identify overlap; they do not prove independence. A null result is not proof of no effect, and a conceptual argument is not a deployment measurement. These paths do not add evidence-to-term relationships.</p><p><a href="../participate/">Have a different question or interpretation? Contribute →</a></p></section>'
 (OUT/'index.html').write_text(page('Question-based research paths','Explore eight AI governance questions through selected public findings, original citations and limitations.',body,1,script=True))
 payload={'format_version':'1.0','editorial_version':VERSION,'dataset_version':d['dataset_version'],'dataset_sha256':hashlib.sha256(raw).hexdigest(),'scope':source['scope'],'verification_note':'Approved public projection, not independent verification. Editorial selection does not create a new evidence-to-term relationship. Source inspection dates are historical; path generation does not re-inspect sources.','paths':jsonpaths}
 (OUT/'paths.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2)+'\n')
 # Discover paths from the Library; preserve existing data and all other links.
 p=D/'evidence/index.html';s=p.read_text();tag='<a href="../questions/">Question-based research paths</a>'
 if tag not in s:s=s.replace('<div class="library-links">','<div class="library-links">'+tag,1)
 p.write_text(s)
 p=D/'sitemap.xml';s=p.read_text()
 for path in paths:
  url=HOST+'questions/'+path['slug']+'/'
  if '<loc>'+url+'</loc>' not in s:s=s.replace('</urlset>','<url><loc>'+url+'</loc></url>\n</urlset>')
 p.write_text(s)
 p=D/'evidence/release-manifest.json';m=json.loads(p.read_text());m['research_paths']={'editorial_version':VERSION,'dataset_version':d['dataset_version'],'dataset_sha256':payload['dataset_sha256'],'files_sha256':{str(x.relative_to(D)):sha(x) for x in sorted(OUT.rglob('*')) if x.is_file()}}
 m['files_sha256']['index.html']=sha(D/'evidence/index.html');p.write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n')
 return payload
if __name__=='__main__':
 result=build();print(json.dumps({'paths':len(result['paths']),'selected_findings':sum(len(p['readings']) for p in result['paths']),'dataset_unchanged':True}))
